"""Isolated WebP/HEIF codec. Paths are generated by Java, never client filenames.

Preserves format, resolution, alpha, orientation, profiles and frame timing.
Already efficient images and HEIF auxiliary/HDR evidence are retained after validation.
"""
import argparse
import io
import json
import os
from pathlib import Path
import sys
import warnings

from PIL import Image, ImageOps, ImageSequence
import pillow_heif

MAX_PIXELS = 40_000_000
MAX_BYTES = 50 * 1024 * 1024
Image.MAX_IMAGE_PIXELS = MAX_PIXELS
warnings.simplefilter('error', Image.DecompressionBombWarning)
pillow_heif.register_heif_opener(decode_threads=2)


def read_frames(data, extension):
    image = Image.open(io.BytesIO(data))
    expected = 'WEBP' if extension == 'webp' else 'HEIF'
    if image.format != expected:
        raise ValueError('image content does not match extension')
    count = getattr(image, 'n_frames', 1)
    if not 1 <= count <= 200:
        raise ValueError('image frame count exceeded')
    frames, pixels = [], 0
    preserve = False
    for i in range(count):
        image.seek(i)
        pixels += image.width * image.height
        if not image.width or not image.height or pixels > MAX_PIXELS:
            raise ValueError('image pixel limit exceeded')
        image.load()
        # These layers cannot be safely reconstructed by the Pillow save API.
        # Keep the validated original instead of silently discarding photographic evidence.
        preserve |= bool(image.info.get('depth_images') or image.info.get('aux')
                         or image.info.get('aux_images') or image.info.get('thumbnails')
                         or image.info.get('bit_depth', 8) > 8)
        frame = image.copy()
        frame.info = dict(image.info)
        # HEIF loader already applies its container transformations and updates EXIF.
        frame = ImageOps.exif_transpose(frame)
        frames.append(frame)
    image.close()
    return frames, preserve


def alpha_digest(image):
    if 'A' not in image.getbands(): return None
    import hashlib
    return hashlib.sha256(image.getchannel('A').tobytes()).hexdigest()


def signature(frames, extension):
    return [(frame.size, alpha_digest(frame), frame.info.get('duration', 0), frame.info.get('loop', 0) if extension == 'webp' else None,
             frame.info.get('primary', i == 0) if extension != 'webp' else None)
            for i, frame in enumerate(frames)]


def normalize(data, extension):
    if extension not in ('webp', 'heic', 'heif') or not 0 < len(data) <= MAX_BYTES:
        raise ValueError('unsupported image or size')
    frames, preserve = read_frames(data, extension)
    if preserve: return data, 'validated-complex-image-retained'
    output = io.BytesIO()
    opts = {'format': 'WEBP' if extension == 'webp' else 'HEIF',
            'quality': 92, 'save_all': True, 'append_images': frames[1:]}
    if extension == 'webp':
        opts.update(method=6, exact=True, duration=[x.info.get('duration', 0) for x in frames],
                    loop=frames[0].info.get('loop', 0))
        for key in ('icc_profile', 'exif', 'xmp'):
            if frames[0].info.get(key): opts[key] = frames[0].info[key]
    else:
        opts['primary_index'] = next((i for i, f in enumerate(frames) if f.info.get('primary')), 0)
        opts['enc_params'] = {'x265:pools': '1', 'x265:frame-threads': '1'}
    frames[0].save(output, **opts)
    candidate = output.getvalue()
    # Re-decode the candidate before returning it. Frame/alpha loss is never accepted.
    decoded, _ = read_frames(candidate, extension)
    if signature(decoded, extension) != signature(frames, extension):
        return data, 'validated-original-retained'
    for before, after in zip(frames, decoded):
        for key in ('icc_profile', 'xmp', 'nclx_profile'):
            if before.info.get(key) != after.info.get(key):
                return data, 'validated-profile-retained'
        if dict(before.getexif()) != dict(after.getexif()):
            return data, 'validated-exif-retained'
    if len(candidate) >= len(data): return data, 'validated-no-size-gain'
    return candidate, 'compressed'


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--input', required=True)
    parser.add_argument('--output', required=True)
    parser.add_argument('--format', required=True, choices=['webp', 'heic', 'heif'])
    args = parser.parse_args()
    if sys.platform.startswith('linux'):
        import resource
        resource.setrlimit(resource.RLIMIT_AS, (1024 ** 3, 1024 ** 3))
        resource.setrlimit(resource.RLIMIT_FSIZE, (MAX_BYTES * 2, MAX_BYTES * 2))
        resource.setrlimit(resource.RLIMIT_CPU, (25, 25))
    source = Path(args.input)
    if source.stat().st_size > MAX_BYTES: raise ValueError('image byte limit exceeded')
    result, decision = normalize(source.read_bytes(), args.format)
    Path(args.output).write_bytes(result)
    print(json.dumps({'status': decision, 'bytes': len(result)}))


if __name__ == '__main__':
    try: main()
    except Exception:
        # Do not expose paths, metadata or native codec diagnostics to callers.
        print('Image decoding or compression failed', file=sys.stderr)
        sys.exit(2)
